const items = $input.all();
const filtered = items.filter(i => {
  const tbl = i.json?.body?.table_name || i.json?.table_name || '';
  return !['rate_limit_log', 'n8n_heartbeat', 'n8n_insights'].includes(tbl);
});
if (filtered.length === 0) return [];
const summary = filtered.map(i => {
  const r = i.json?.body?.record || i.json?.body || i.json;
  return { table: r.table_name, action: r.action, user: r.user_email, role: r.user_role, time: r.created_at || r.timestamp };
});
return [{ json: { count: filtered.length, records: summary } }];

const t = $input.item.json.text || $input.item.json.content || '{}';
let p;
try { p = typeof t === 'string' ? JSON.parse(t) : t; } catch { p = { analyses: [] }; }
const analyses = p.analyses || [];
const results = [];
for (const a of analyses) {
  if (a.severity === 'warning' || a.severity === 'critical') {
    results.push({ json: a });
  }
}
return results.length > 0 ? results : [{ json: { skip: true } }];
